// $Barnyard: FUNCTION 0056cd20
APoolBallSteer::APoolBallSteer()
    : m_fMinSpeed( 0.05f )
    , m_fFriction( -0.85f )
    , m_fRadius( 0.045f )
    , m_iUnk24( 0 )
    , m_vecPosition( TVector4::VEC_ZERO )
    , m_vecVelocity( TVector4::VEC_ZERO )
    , m_vecDirection( TVector4::VEC_POSX )
    , m_vecPottedPosition( TVector4::VEC_ZERO )
    , m_eState( STATE_MOVING )
    , m_pFirstHitUnit( TNULL )
    , m_bHitBall( TFALSE )
    , m_bHitCushion( TFALSE )
    , m_bHitPocket( TFALSE )
{
}

