// $Barnyard: FUNCTION 0056ce40
TBOOL APoolBallSteer::Create( AUnit* a_pOwner, const TVector4& a_rcPosition, const TVector4& a_rcDirection, TINT a_iLOD )
{
	ASteer::Create( a_pOwner, a_rcPosition, a_rcDirection, a_iLOD );

	m_vecPosition  = a_rcPosition;
	m_vecDirection = a_rcDirection;
	m_vecVelocity  = TVector4::VEC_ZERO;
	m_eState       = STATE_MOVING;

	return TTRUE;
}

// $Barnyard: FUNCTION 0056ced0
TBOOL APoolBallSteer::CreateFrom( ASteer* a_pOther, TINT a_iLOD )
{
	ASteer::CreateFrom( a_pOther, a_iLOD );

	a_pOther->CopyPosition( m_vecPosition );
	a_pOther->CopyDirection( m_vecDirection );
	a_pOther->CopyVelocity( m_vecVelocity );
	m_eState = STATE_MOVING;

	return TTRUE;
}

// $Barnyard: FUNCTION 0056de60
TBOOL APoolBallSteer::Update( TFLOAT a_fDeltaTime )
{
	if ( m_eState == STATE_MOVING )
	{
		m_vecPosition.y = m_vecTableCenter.y;
		UpdateMoving( a_fDeltaTime );
	}
	else if ( m_eState == STATE_FALLING_POCKET )
	{
		UpdateFallingPocket( a_fDeltaTime );
		return TTRUE;
	}

	return TTRUE;
}

// $Barnyard: FUNCTION 0056cf70
TBOOL APoolBallSteer::SetPosition( const TVector4& a_rcPosition )
{
	m_vecPosition = a_rcPosition;
	m_vecVelocity = TVector4::VEC_ZERO;
	m_eState      = STATE_STOPPED;

	return TTRUE;
}

