TBOOL APoolBallSteer::SetPosition3( const TVector3& a_rcPosition )
{
	m_vecPosition.Set( a_rcPosition.x, a_rcPosition.y, a_rcPosition.z, 1.0f );
	m_vecVelocity = TVector4::VEC_ZERO;
	m_eState      = STATE_STOPPED;

	return TTRUE;
}

