// $Barnyard: FUNCTION 0056d690
TBOOL APoolBallSteer::IsTouchingOtherBall()
{
	AUnit* pOwner = m_oOwner->GetUnit();

	auto& llUnits = AUnitManager::GetSingleton()->GetUnits();

	for ( auto it = llUnits.Begin(); it != llUnits.End(); it++ )
	{
		AUnit* pUnit = it;

		if ( pOwner != pUnit && pUnit->GetSteer()->IsA( &TGetClass( APoolBallSteer ) ) )
		{
			TFLOAT   fOtherRadius   = pUnit->GetSteer()->GetRadius();
			TVector4 vecOtherCenter = *pUnit->GetSteer()->GetPosition();

			if ( TMath::SphereVsSphere( m_vecPosition, m_fRadius, vecOtherCenter, fOtherRadius ) )
				return TTRUE;
		}
	}

	return TFALSE;
}

// $Barnyard: FUNCTION 0056d1b0
TBOOL APoolBallSteer::UpdateFallingPocket( TFLOAT a_fDeltaTime )
{
	// The ball moves to a point above the center of the pocket
	TVector4 vecTarget = m_pPockets[ m_iPocket ];
	vecTarget.y += m_fRadius + m_fRadius;

	if ( m_vecPosition.IsEqual( vecTarget ) )
	{
		SetPosition( m_vecPottedPosition );
		m_eState = STATE_POTTED;
		return TTRUE;
	}

	TVector4 vecDirection( vecTarget.x - m_vecPosition.x, vecTarget.y - m_vecPosition.y, vecTarget.z - m_vecPosition.z, vecTarget.w );
	vecDirection.Normalise();

	TFLOAT   fDistanceSq    = TVector4::DistanceSq( vecTarget, m_vecPosition );
	TVector4 vecOldPosition = m_vecPosition;

	TVector4 vecMove;
	vecMove.Multiply( vecDirection, a_fDeltaTime );
	vecMove.Multiply( vecMove, 2.0f );

	m_vecPosition.x += vecMove.x;
	m_vecPosition.y += vecMove.y;
	m_vecPosition.z += vecMove.z;

	// Don't move past the target
	if ( TVector4::DistanceSq( m_vecPosition, vecOldPosition ) > fDistanceSq )
		m_vecPosition = vecTarget;

	return TTRUE;
}

// $Barnyard: FUNCTION 0056d360
TBOOL APoolBallSteer::CollidePockets( const TVector4& a_rcPosition, const TVector4& a_rcDirection, TFLOAT& a_rfDistance, TINT& a_riPocket, TINT a_iNumPockets, TFLOAT a_fRadius, const TVector4* a_pPockets, TFLOAT a_fPocketRadius )
{
	TBOOL bHit = TFALSE;

	for ( TINT i = a_iNumPockets - 1; i >= 0; i-- )
	{
		const TVector4& rcPocket = a_pPockets[ i ];

		if ( TMath::SphereVsSphere( a_rcPosition, a_fRadius, rcPocket, a_fPocketRadius ) )
		{
			// Already in the pocket
			a_rfDistance = 0.0f;
			a_riPocket   = i;
			bHit         = TTRUE;
		}
		else
		{
			TVector4 vecNormal;

			if ( TMath::SweptSphereVsSphere( a_rcPosition, a_fRadius, a_rcDirection, rcPocket, a_fPocketRadius, a_rfDistance, vecNormal, 0.001f ) == TTRUE )
			{
				if ( a_rfDistance < 0.0f )
					a_rfDistance = 0.0f;

				a_riPocket = i;
				bHit       = TTRUE;
			}
		}
	}

	return bHit;
}

// $Barnyard: FUNCTION 0056d550
TBOOL APoolBallSteer::CollideBalls( const TVector4& a_rcPosition, const TVector4& a_rcDirection, TFLOAT& a_rfDistance, AUnit*& a_rpHitUnit, AUnit* a_pIgnoreUnit, TFLOAT a_fRadius )
{
	TBOOL bHit = TFALSE;

	auto& llUnits = AUnitManager::GetSingleton()->GetUnits();

	for ( auto it = llUnits.Begin(); it != llUnits.End(); it++ )
	{
		AUnit* pUnit = it;

		if ( a_pIgnoreUnit == pUnit || !pUnit->GetSteer()->IsA( &TGetClass( APoolBallSteer ) ) )
			continue;

		APoolBallSteer* pSteer = TSTATICCAST( APoolBallSteer, pUnit->GetSteer() );

		// Balls in the pockets are ignored
		if ( pSteer->m_eState == STATE_FALLING_POCKET || pSteer->m_eState == STATE_POTTED )
			continue;

		// NOTE: retail gets the radius of the other ball but uses a_fRadius for both
		pSteer->GetRadius();
		TVector4 vecOtherCenter = *pUnit->GetSteer()->GetPosition();

		// NOTE: unused in retail
		TVector4 vecMove;
		vecMove.Multiply( a_rcDirection, a_rfDistance );

		TVector4 vecNormal;

		if ( TMath::SweptSphereVsSphere( a_rcPosition, a_fRadius, a_rcDirection, vecOtherCenter, a_fRadius, a_rfDistance, vecNormal, 0.001f ) == TTRUE )
		{
			if ( a_rfDistance < 0.0f )
				a_rfDistance = 0.0f;

			a_rpHitUnit = pUnit;
			bHit        = TTRUE;

			// NOTE: unused in retail
			TVector4 vecHitMove;
			vecHitMove.Multiply( a_rcDirection, a_rfDistance );
		}
	}

	return bHit;
}

// $Barnyard: FUNCTION 0056d760
void APoolBallSteer::UpdateMoving( TFLOAT a_fDeltaTime )
{
	if ( m_vecVelocity.IsEqual( TVector4::VEC_ZERO ) )
	{
		if ( m_eState == STATE_STOPPED )
			return;

		m_eState      = STATE_STOPPED;
		m_vecVelocity = TVector4::VEC_ZERO;
		return;
	}

	// Friction
	TVector4 vecFriction;
	vecFriction.Multiply( m_vecVelocity, m_fFriction );
	TVector4 vecFrictionStep;
	vecFrictionStep.Multiply( vecFriction, a_fDeltaTime );

	m_vecVelocity.x += vecFrictionStep.x;
	m_vecVelocity.y += vecFrictionStep.y;
	m_vecVelocity.z += vecFrictionStep.z;

	// m_vecVelocity is the direction of the movement from now on
	TFLOAT fSpeed             = m_vecVelocity.NormaliseMag();
	AUnit* pHitUnit           = TNULL;
	TINT   iPocket            = -1;
	TINT   iNumCollisions     = 0;
	TFLOAT fRemainingDistance = fSpeed * a_fDeltaTime;

	do
	{
		TFLOAT   fDistance = fRemainingDistance;
		TVector4 vecCushionNormal;
		TFLOAT   fStepHeight;
		TFLOAT   fPenetration;

		TBOOL bHitCushion = ATerrainInterface::GetSingleton()->CollideSweptSphere( m_vecPosition, m_fRadius, m_vecVelocity, fDistance, vecCushionNormal, 0.01f, fStepHeight, fPenetration, 0 );
		TBOOL bHitBall    = CollideBalls( m_vecPosition, m_vecVelocity, fDistance, pHitUnit, m_oOwner->GetUnit(), m_fRadius );
		TBOOL bHitPocket  = CollidePockets( m_vecPosition, m_vecVelocity, fDistance, iPocket, m_iNumPockets, m_fRadius, m_pPockets, m_fPocketRadius );

		// Move to the closest hit
		TVector4 vecMove;
		vecMove.Multiply( m_vecVelocity, fDistance );

		m_vecPosition.x += vecMove.x;
		m_vecPosition.y += vecMove.y;
		m_vecPosition.z += vecMove.z;

		fRemainingDistance -= fDistance;

		if ( bHitPocket == TTRUE )
		{
			m_bHitPocket       = TTRUE;
			m_vecVelocity      = TVector4::VEC_ZERO;
			m_iPocket          = iPocket;
			m_eState           = STATE_FALLING_POCKET;
			fRemainingDistance = 0.0f;
		}
		else if ( bHitBall == TTRUE )
		{
			// Elastic collision of two balls of the same mass, the velocities along the line between the centers are swapped
			m_vecVelocity.Multiply( fSpeed );

			ASteer*  pOtherSteer      = pHitUnit->GetSteer();
			TVector4 vecOtherVelocity = pOtherSteer->GetVelocity();

			const TVector4* pOtherPosition = pHitUnit->GetSteer()->GetPosition();
			TVector4        vecToOther( pOtherPosition->x - m_vecPosition.x, pOtherPosition->y - m_vecPosition.y, pOtherPosition->z - m_vecPosition.z, pOtherPosition->w );
			vecToOther.Normalise();

			TFLOAT fDot      = TVector4::DotProduct3( m_vecVelocity, vecToOther );
			TFLOAT fOtherDot = TVector4::DotProduct3( vecOtherVelocity, vecToOther );

			if ( fDot > 0.0f || fOtherDot < 0.0f )
			{
				m_bHitBall = TTRUE;

				if ( !m_pFirstHitUnit )
					m_pFirstHitUnit = pHitUnit;

				TFLOAT fExchange = fDot - fOtherDot;

				TVector4 vecExchange;
				vecExchange.Multiply( vecToOther, fExchange );
				TVector4 vecNewVelocity( m_vecVelocity.x - vecExchange.x, m_vecVelocity.y - vecExchange.y, m_vecVelocity.z - vecExchange.z, m_vecVelocity.w );

				TVector4 vecOtherExchange;
				vecOtherExchange.Multiply( vecToOther, fExchange );
				TVector4 vecNewOtherVelocity( vecOtherExchange.x + vecOtherVelocity.x, vecOtherExchange.y + vecOtherVelocity.y, vecOtherExchange.z + vecOtherVelocity.z, vecOtherVelocity.w );

				SetVelocity( vecNewVelocity );
				pHitUnit->GetSteer()->SetVelocity( vecNewOtherVelocity );
			}

			fSpeed = m_vecVelocity.NormaliseMag();

			if ( fSpeed < m_fMinSpeed )
			{
				m_eState           = STATE_STOPPED;
				m_vecVelocity      = TVector4::VEC_ZERO;
				fSpeed             = 0.0f;
				fRemainingDistance = 0.0f;
			}
		}
		else if ( bHitCushion == TTRUE )
		{
			// Reflect the direction off the cushion (in the plane of the table)
			m_bHitCushion = TTRUE;

			vecCushionNormal.y = 0.0f;
			vecCushionNormal.Normalise();

			TFLOAT fDot = TVector4::DotProduct3( vecCushionNormal, m_vecVelocity );

			TVector4 vecReflect;
			vecReflect.Multiply( vecCushionNormal, fDot + fDot );

			m_vecVelocity.x -= vecReflect.x;
			m_vecVelocity.y -= vecReflect.y;
			m_vecVelocity.z -= vecReflect.z;
			m_vecVelocity.y = 0.0f;
			m_vecVelocity.Normalise();
		}

		iNumCollisions++;
	} while ( iNumCollisions < MAX_NUM_COLLISIONS && fRemainingDistance > 0.0f );

	if ( fSpeed < m_fMinSpeed )
	{
		m_eState      = STATE_STOPPED;
		m_vecVelocity = TVector4::VEC_ZERO;
		return;
	}

	m_vecVelocity.Multiply( fSpeed );
}
